<template>
  <view class="app-shell">
    <view class="sidebar">
      <view class="brand" @click="activePage = 'discover'">
        <view class="brand-mark"><view class="petal petal-one"></view><view class="petal petal-two"></view><view class="petal petal-three"></view><view class="petal petal-four"></view></view>
        <text class="brand-name">一点<text class="brand-period">.</text></text>
      </view>
      <text class="brand-tagline">让善意，刚好发生</text>
      <view class="nav-list">
        <button v-for="item in navigation" :key="item.id" :class="['nav-item', { active: activePage === item.id }]" @click="activePage = item.id">
          <AppIcon :name="activePage === item.id ? item.icon + '-orange' : item.icon" :size="21" />
          <text>{{ item.label }}</text><text v-if="item.id === 'history' && contributions.length" class="nav-count">{{ contributions.length }}</text><view v-if="activePage === item.id" class="nav-dot"></view>
        </button>
      </view>
      <view class="sidebar-note"><view class="note-flower">✳</view><text class="note-heading">世界的好，与你有关。</text><text class="note-copy">不必成为谁的英雄，<br />一点点善意，就很了不起。</text><view class="note-line"></view><text class="note-foot">SMALL ACTS. BIG HEARTS.</text></view>
      <view class="sidebar-bottom"><button class="sidebar-link" @click="modal = 'about'"><AppIcon name="shield" :size="17" />信任与安全<AppIcon name="arrow-up-right" :size="14" /></button><view class="side-divider"></view><button class="profile-mini" @click="activePage = 'profile'"><view class="my-avatar">Y</view><view class="profile-mini-text"><text class="profile-name">一位有心人</text><text class="profile-subtitle">今天也让善意发生</text></view><AppIcon name="chevron-right" :size="16" /></button></view>
    </view>

    <view class="main">
      <view class="topbar"><view class="breadcrumb"><text>一点善意</text><text class="breadcrumb-slash">/</text><text class="breadcrumb-current">{{ currentPageLabel }}</text></view><view class="topbar-actions"><view class="demo-indicator"><view class="green-dot"></view><text>善意正在发生</text></view><button class="notification-button" aria-label="消息通知" @click="modal = 'notifications'"><AppIcon name="bell" :size="20" /><view class="notification-dot"></view></button><view class="topbar-divider"></view><button class="publish-button" @click="openPublish"><AppIcon name="plus-white" :size="16" /><text>发布我的账单</text></button></view></view>

      <view v-if="activePage === 'discover'" class="page-content">
        <view class="hero"><view><view class="eyebrow"><view class="small-spark">✳</view><text>A LITTLE KINDNESS, A BIG DIFFERENCE</text></view><view class="hero-title">生活偶尔有点难，<br />还好有<text class="orange-word">你在。</text><view class="title-spark">✧</view></view><text class="hero-description">看见一个故事，接住一份不容易。让你的善意，刚好被需要。</text></view><view class="hero-community"><view class="avatar-stack"><image v-for="(src, i) in avatarImages" :key="i" :src="src" mode="aspectFill" :style="{ zIndex: 5 - i }" /><view class="avatar-more">+1k</view></view><text class="community-line"><text class="community-number">1,286</text> 位有心人，与你一起</text><text class="community-caption">把小小善意，变成生活里的光</text></view></view>

        <view class="discovery-toolbar"><view class="categories"><button v-for="category in categories" :key="category.id" :class="['category-button', { selected: activeCategory === category.id }]" @click="activeCategory = category.id"><AppIcon :name="activeCategory === category.id ? category.icon + '-orange' : category.icon" :size="17" /><text>{{ category.label }}</text></button></view><button :class="['filter-button', { 'has-filter': maxAmount < 10000 || sortOrder === 'latest' }]" @click="modal = 'filters'"><AppIcon name="sliders" :size="17" /><text>筛选</text></button></view>

        <view class="discovery-layout">
          <view class="swipe-column">
            <view class="section-kicker"><view class="live-dot"></view><text>遇见一份需要</text><text class="card-counter">{{ available.length ? '01' : '00' }} <text class="counter-divider">/</text> {{ String(available.length).padStart(2, '0') }}</text></view>
            <view v-if="currentBill" class="card-stage">
              <view class="card-behind behind-two"></view><view class="card-behind behind-one"></view>
              <view :class="['story-card', { dragging: isDragging, 'is-leaving': leaving }]" :style="cardStyle" @touchstart="startDrag" @touchmove="moveDrag" @touchend="endDrag" @touchcancel="cancelDrag" @mousedown="startDrag" @mousemove="moveDrag" @mouseup="endDrag" @mouseleave="endDrag">
                <image class="story-image" :src="currentBill.image" mode="aspectFill" :style="{ objectPosition: currentBill.imagePosition }" :draggable="false" />
                <view class="story-shade"></view><view class="story-top"><view class="verified-label"><AppIcon name="shield-white" :size="13" /><text>演示账单</text></view><button class="bookmark-button" :aria-label="saved.includes(currentBill.id) ? '取消收藏' : '收藏账单'" @click.stop="toggleSave(currentBill.id)"><AppIcon :name="saved.includes(currentBill.id) ? 'bookmark-orange' : 'bookmark-white'" :size="20" /></button></view>
                <view v-if="dragX > 45" class="swipe-stamp yes-stamp">帮一把 ♡</view><view v-if="dragX < -45" class="swipe-stamp no-stamp">下次有缘</view>
                <view class="story-content"><view class="person-tag"><view class="person-dot"></view>{{ currentBill.tag }}</view><view class="person-name">{{ currentBill.name }}<text class="person-age">{{ currentBill.age }}</text><AppIcon name="badge-white" :size="18" /></view><view class="person-location"><AppIcon name="pin-white" :size="13" />{{ currentBill.city }}<text class="location-separator">·</text>{{ categoryLabel(currentBill.category) }}</view><text class="story-title">{{ currentBill.title }}</text><text class="story-excerpt">{{ currentBill.subtitle }}</text><view class="card-bottom-line"><view class="card-amount"><text class="amount-currency">¥</text>{{ money(currentBill.amount - currentBill.raised) }}<text class="amount-label">待帮助</text></view><button class="story-details-button" @click.stop="modal = 'details'">听听 TA 的故事<AppIcon name="arrow-right-white" :size="16" /></button></view></view>
              </view>
            </view>
            <view v-else class="empty-card"><view class="empty-flower">✳</view><text class="empty-title">每一份善意，都值得等待</text><text class="empty-copy">这个分类的账单已经看完啦，<br />换个分类，或再看看刚才的故事。</text><button class="primary-button" @click="resetDiscovery">重新发现</button></view>
            <view class="swipe-actions"><button class="round-action undo-action" aria-label="撤销上一次略过" :disabled="!skipped.length || leaving" @click="undoSkip"><AppIcon name="undo" :size="22" /></button><view class="action-group"><button class="round-action skip-action" aria-label="略过这张账单" :disabled="!currentBill || leaving" @click="skipBill"><AppIcon name="close" :size="29" /></button><text>下次有缘</text></view><view class="action-group"><button class="round-action help-action" aria-label="帮助这张账单" :disabled="!currentBill || leaving" @click="openHelp"><AppIcon name="heart-white" :size="31" /></button><text>帮 TA 一把</text></view><button class="round-action small-save" aria-label="收藏当前账单" :disabled="!currentBill" @click="currentBill && toggleSave(currentBill.id)"><AppIcon :name="currentBill && saved.includes(currentBill.id) ? 'bookmark-orange' : 'bookmark'" :size="22" /></button></view>
            <view class="swipe-hint"><AppIcon name="swipe" :size="17" /><text>左滑略过，右滑帮助，善意随心而动</text></view>
          </view>

          <view class="information-column">
            <view class="bill-panel"><view class="panel-header"><view class="panel-heading"><AppIcon name="receipt" :size="20" /><text>这是一张怎样的账单</text></view><view class="paper-corner"></view></view><template v-if="currentBill"><view class="bill-category-label">{{ categoryLabel(currentBill.category) }}<text> · {{ currentBill.city }}</text></view><view class="bill-title">{{ currentBill.billName }}</view><view class="bill-total"><text class="bill-currency">¥</text>{{ money(currentBill.amount) }}<text class="bill-unit">账单总额</text></view><view class="progress-track"><view class="progress-fill" :style="{ width: `${Math.min(100, currentBill.raised / currentBill.amount * 100)}%` }"></view></view><view class="progress-labels"><text>已被接住 <text class="orange-text">¥{{ money(currentBill.raised) }}</text></text><text>{{ Math.round(currentBill.raised / currentBill.amount * 100) }}%</text></view><view class="receipt-divider"><view></view><view></view></view><view class="bill-story"><text class="quote-mark">“</text><text>{{ currentBill.story }}</text></view><button class="read-more" @click="modal = 'details'">了解完整故事<AppIcon name="arrow-right-orange" :size="15" /></button><view class="bill-panel-footer"><AppIcon name="heart" :size="14" /><text>已经有 {{ currentBill.people }} 位有心人送出善意</text></view></template><view v-else class="panel-empty">下一份故事，等待与你相遇。</view></view>
            <view class="promise-panel"><view class="promise-icon"><AppIcon name="shield" :size="22" /></view><view><text class="promise-title">每一点善意，都有迹可循</text><text class="promise-copy">真实账单 · 隐私保护 · 进度透明</text></view><button aria-label="了解信任与安全" @click="modal = 'about'"><AppIcon name="chevron-right" :size="17" /></button></view>
            <view class="daily-quote"><text class="quote-eyebrow">TODAY'S LITTLE REMINDER</text><text class="daily-quote-text">“ 你的一点点，<br /><text>是别人生活里的一大步。</text> ”</text><view class="quote-signature"><view></view>一点 · 善意手记<AppIcon name="sun" :size="23" /></view></view>
          </view>
        </view>
        <view class="impact-strip"><view class="impact-intro"><view class="impact-heart"><AppIcon name="heart-orange" :size="20" /></view><view><text class="impact-title">小小善意，正在汇成光</text><text class="impact-caption">每一个数字背后，都是被温柔接住的生活</text></view></view><view class="impact-stat"><text>2,369<text class="stat-suffix"> 张</text></text><text class="stat-label">账单被接住</text></view><view class="impact-stat"><text>128,650<text class="stat-suffix"> 元</text></text><text class="stat-label">善意已送达</text></view><view class="impact-stat"><text>1,286<text class="stat-suffix"> 位</text></text><text class="stat-label">有心人同行</text></view></view>
        <view class="page-footer"><text>不用很多，一点就好。</text><text>演示体验 · 所有人物与账单故事均为虚构</text></view>
      </view>

      <view v-else-if="activePage === 'history'" class="page-content secondary-page"><view class="eyebrow"><view class="small-spark">✳</view>YOUR KINDNESS MATTERS</view><view class="secondary-title">我的<text class="orange-word">善意足迹。</text></view><text class="hero-description">每一次伸出手，都在让某个人的生活好一点。</text><view class="personal-stats"><view><text class="personal-number">{{ contributions.length }}</text><text>次温暖相助</text></view><view><text class="personal-number">¥{{ money(totalContributed) }}</text><text>累计模拟帮助</text></view><view><text class="personal-number">{{ new Set(contributions.map(c => c.billId)).size }}</text><text>个被接住的故事</text></view></view><view v-if="!contributions.length" class="list-empty"><AppIcon name="heart-orange" :size="44" /><text class="empty-title">你的第一份善意，从这里开始</text><text class="empty-copy">去看看那些认真生活的人，遇见一个想帮助的故事。</text><button class="primary-button" @click="activePage = 'discover'">去发现账单<AppIcon name="arrow-right-white" :size="17" /></button></view><view v-for="record in contributions" :key="record.id" class="history-row"><view class="history-icon"><AppIcon name="heart-orange" :size="24" /></view><view class="history-copy"><text class="history-title">帮助了{{ record.name }} · {{ record.billName }}</text><text class="history-date">{{ record.date }} · 模拟帮助已记录</text></view><text class="history-amount">¥{{ money(record.amount) }}</text></view></view>

      <view v-else-if="activePage === 'saved'" class="page-content secondary-page"><view class="eyebrow"><view class="small-spark">✳</view>STORIES CLOSE TO YOUR HEART</view><view class="secondary-title">留在心里的<text class="orange-word">故事。</text></view><text class="hero-description">把想再看一眼的故事，放在这里。</text><view v-if="!savedBills.length" class="list-empty"><AppIcon name="bookmark-orange" :size="44" /><text class="empty-title">收藏一份让你心动的故事</text><text class="empty-copy">点击账单上的收藏按钮，就能在这里再次遇见 TA。</text><button class="primary-button" @click="activePage = 'discover'">去发现账单</button></view><view class="saved-grid"><view v-for="bill in savedBills" :key="bill.id" class="saved-card"><image :src="bill.image" mode="aspectFill" /><view class="saved-card-copy"><view class="saved-card-top"><text>{{ bill.name }} · {{ bill.city }}</text><button aria-label="取消收藏" @click="toggleSave(bill.id)"><AppIcon name="bookmark-orange" :size="20" /></button></view><text class="saved-title">{{ bill.title }}</text><view class="saved-card-bottom"><text>待帮助 <text class="orange-text">¥{{ money(Math.max(0, bill.amount - bill.raised)) }}</text></text><button @click="showSavedBill(bill)">看看故事<AppIcon name="arrow-right-orange" :size="16" /></button></view></view></view></view></view>

      <view v-else class="page-content secondary-page"><view class="eyebrow"><view class="small-spark">✳</view>EVERY LITTLE BIT OF YOU</view><view class="secondary-title">你好，<text class="orange-word">有心人。</text></view><text class="hero-description">愿你被生活温柔以待，也把这份温柔传递下去。</text><view class="profile-card"><view class="profile-avatar">Y</view><view><text class="profile-big-name">一位有心人</text><text class="profile-description">本地演示账号 · 数据仅保存在当前设备</text></view><view class="profile-badge"><AppIcon name="heart-orange" :size="16" />善意同行者</view></view><view class="profile-menu"><button @click="activePage = 'history'"><AppIcon name="heart" /><text>我的帮助记录</text><AppIcon name="chevron-right" :size="17" /></button><button @click="openPublish"><AppIcon name="receipt" /><text>发布我的账单</text><AppIcon name="chevron-right" :size="17" /></button><button @click="modal = 'about'"><AppIcon name="shield" /><text>信任、隐私与平台说明</text><AppIcon name="chevron-right" :size="17" /></button></view><view class="my-bills-heading">我发布的账单 <text>{{ myBills.length }}</text></view><view v-if="!myBills.length" class="empty-copy">还没有发布账单。有需要的时候，也可以让别人接住你。</view><view v-for="bill in myBills" :key="bill.id" class="history-row"><AppIcon name="receipt" :size="24" /><view class="history-copy"><text class="history-title">{{ bill.billName }}</text><text class="history-date">本地演示 · 未提交平台审核</text></view><text class="orange-text">¥{{ money(bill.amount) }}</text></view></view>
    </view>

    <view class="mobile-nav"><button v-for="item in navigation" :key="item.id" :class="{ 'mobile-active': activePage === item.id }" @click="activePage = item.id"><AppIcon :name="activePage === item.id ? item.icon + '-orange' : item.icon" :size="22" /><text>{{ item.label }}</text></button></view>

    <view v-if="modal" class="modal-overlay" @click="closeModal"><view :class="['modal', { 'wide-modal': modal === 'publish' }]" @click.stop><view class="modal-header"><view class="modal-brand"><AppIcon name="heart-orange" :size="20" /><text>一点善意</text></view><button class="modal-close" aria-label="关闭弹窗" @click="closeModal"><AppIcon name="close" :size="22" /></button></view>
      <view v-if="modal === 'help' && currentBill" class="modal-body"><view class="modal-title">给{{ currentBill.name }}，一点温暖。</view><text class="modal-description">{{ currentBill.billName }} · 还需 ¥{{ money(remaining) }}</text><view class="help-amount-options"><button v-for="amount in helpPresets" :key="amount" :class="{ chosen: Number(helpAmount) === amount }" @click="helpAmount = String(amount)">¥{{ money(amount) }}</button></view><view class="amount-input-wrap"><text>¥</text><input v-model="helpAmount" type="digit" placeholder="自定义帮助金额" maxlength="9" /></view><text v-if="helpError" class="form-error">{{ helpError }}</text><view class="simulation-note"><AppIcon name="shield" :size="18" /><text>当前为演示体验，确认后仅记录模拟帮助，不会产生付款。</text></view><button class="primary-button full-button" @click="confirmHelp"><AppIcon name="heart-white" :size="19" />确认送出善意 · ¥{{ money(Number(helpAmount) || 0) }}</button><text class="modal-fineprint">一点不多，刚好足够温暖一个人。</text></view>
      <view v-else-if="modal === 'success'" class="modal-body success-body"><view class="success-heart"><AppIcon name="heart-orange" :size="44" /></view><view class="modal-title">你的善意，已被接住。</view><text class="modal-description">已记录 ¥{{ money(lastContribution) }} 的模拟帮助。<br />谢谢你，愿意让一个普通的日子亮起来。</text><button class="primary-button full-button" @click="closeModal">继续遇见需要的人</button><button class="text-button" @click="modal = ''; activePage = 'history'">看看我的善意足迹</button></view>
      <view v-else-if="modal === 'details' && currentBill" class="modal-body"><view class="detail-person"><image :src="currentBill.image" mode="aspectFill" /><view><text class="detail-name">{{ currentBill.name }}，{{ currentBill.age }}</text><text class="modal-description">{{ currentBill.city }} · {{ currentBill.tag }}</text></view></view><view class="modal-title">{{ currentBill.title }}</view><text class="detail-story">{{ currentBill.story }}</text><view class="detail-receipt"><view><text>账单项目</text><text>{{ currentBill.billName }}</text></view><view><text>支出类别</text><text>{{ currentBill.billType }}</text></view><view><text>账单日期</text><text>{{ currentBill.date }}</text></view><view><text>账单金额</text><text>¥{{ money(currentBill.amount) }}</text></view><view><text>尚需帮助</text><text class="orange-text">¥{{ money(remaining) }}</text></view></view><text class="detail-quote">“{{ currentBill.quote }}”</text><text class="modal-fineprint">虚构故事及示意照片，仅用于产品演示；未经过真实身份或票据审核。</text><button class="primary-button full-button" @click="openHelp"><AppIcon name="heart-white" :size="19" />我想帮 TA 一把</button></view>
      <view v-else-if="modal === 'filters'" class="modal-body"><view class="modal-title">遇见刚好能帮上的人</view><text class="modal-description">选择适合自己的帮助范围，善意不用勉强。</text><text class="form-label">待帮助金额</text><view class="filter-options"><button v-for="option in amountFilters" :key="option.value" :class="{ chosen: draftMax === option.value }" @click="draftMax = option.value">{{ option.label }}</button></view><text class="form-label">排列方式</text><view class="filter-options"><button :class="{ chosen: draftSort === 'recommended' }" @click="draftSort = 'recommended'">为你推荐</button><button :class="{ chosen: draftSort === 'latest' }" @click="draftSort = 'latest'">最新发布</button></view><button class="primary-button full-button" @click="applyFilters">查看符合条件的账单</button><button class="text-button" @click="draftMax = 10000; draftSort = 'recommended'">重置筛选</button></view>
      <view v-else-if="modal === 'publish'" class="modal-body"><view class="modal-title">有时候，你也可以被接住。</view><text class="modal-description">说说你的需要。我们相信，每一个认真生活的人。</text><text class="form-label">给故事起个名字 <text>*</text></text><input v-model="publishForm.title" class="form-input" placeholder="例如：想把日子，慢慢过好" maxlength="28" /><view class="form-two-columns"><view><text class="form-label">账单名称 <text>*</text></text><input v-model="publishForm.billName" class="form-input" placeholder="例如：一周的生活采购" maxlength="30" /></view><view><text class="form-label">账单金额（元）<text>*</text></text><input v-model="publishForm.amount" class="form-input" type="digit" placeholder="1–10,000" maxlength="8" /></view></view><text class="form-label">账单类别</text><picker :range="publicationCategories" range-key="label" :value="publicationCategories.findIndex(c => c.id === publishForm.category)" @change="publishForm.category = publicationCategories[Number($event.detail.value)].id"><view class="form-input picker-input">{{ categoryLabel(publishForm.category) }}<AppIcon name="chevron-down" :size="16" /></view></picker><text class="form-label">你的故事 <text>*</text></text><textarea v-model="publishForm.story" class="form-textarea" placeholder="最近遇到了什么困难？这张账单对你意味着什么？请不要填写身份证、银行卡等敏感信息。" maxlength="300" /><text class="character-count">{{ publishForm.story.length }} / 300</text><button class="agreement-row" @click="publishForm.agreed = !publishForm.agreed"><view :class="['checkbox', { checked: publishForm.agreed }]"><text v-if="publishForm.agreed">✓</text></view><text>我确认信息真实，并同意对公开内容做隐私保护处理。</text></button><text v-if="publishError" class="form-error">{{ publishError }}</text><view class="simulation-note"><AppIcon name="shield" :size="17" /><text>演示账单只保存在此设备，不会对外发布或进入真实审核。</text></view><button class="primary-button full-button" @click="submitPublication">保存我的演示账单<AppIcon name="arrow-right-white" :size="17" /></button></view>
      <view v-else-if="modal === 'notifications'" class="modal-body"><view class="modal-title">来自一点的小消息</view><view class="notification-entry"><view class="history-icon"><AppIcon name="sun" :size="23" /></view><view><text class="history-title">欢迎来到一点</text><text class="notification-copy">在这里，不需要成为英雄。一点小小的善意，就能给某个人带来温暖。</text><text class="history-date">今天 · 系统消息</text></view></view><view v-if="contributions.length" class="notification-entry"><view class="history-icon"><AppIcon name="heart-orange" :size="23" /></view><view><text class="history-title">谢谢你，让善意发生</text><text class="notification-copy">你已经送出了 {{ contributions.length }} 次模拟帮助，每一份都已记在善意足迹里。</text><button class="read-more" @click="modal = ''; activePage = 'history'">查看善意足迹<AppIcon name="arrow-right-orange" :size="16" /></button></view></view></view>
      <view v-else class="modal-body"><view class="modal-title">让善意，安心发生。</view><text class="about-intro">一点，是一个让普通人互相接住的地方。我们希望每一份帮助，都建立在尊重和信任之上。</text><view class="about-item"><AppIcon name="receipt" :size="23" /><view><text>真实与透明</text><text>当前展示的是虚构账单。正式上线需要接入实名认证、票据审核、风险控制和可追溯的资金记录。</text></view></view><view class="about-item"><AppIcon name="shield" :size="23" /><view><text>保护每个人的隐私</text><text>展示昵称和必要的故事，不公开身份证、联系方式、地址或金融账户等敏感信息。</text></view></view><view class="about-item"><AppIcon name="heart-orange" :size="23" /><view><text>帮助随心，量力而行</text><text>本版本只演示帮助流程，不收款、不转账。统计数字为示意，照片来自 Unsplash，与虚构人物无关。</text></view></view><button class="primary-button full-button" @click="closeModal">带着善意，继续发现</button></view>
    </view></view>
    <view v-if="toast" class="toast"><AppIcon name="check-white" :size="18" /><text>{{ toast }}</text></view>
  </view>
</template>

<script setup>
import { ref, computed, watch, onUnmounted } from 'vue'
import AppIcon from '../../components/AppIcon.vue'
import { categories, initialBills, eligibleBills, validatePublication, validateHelpAmount } from '../../data/bills.js'

const navigation = [{ id: 'discover', label: '发现账单', icon: 'compass' }, { id: 'history', label: '我的帮助', icon: 'heart' }, { id: 'saved', label: '我的收藏', icon: 'bookmark' }, { id: 'profile', label: '个人中心', icon: 'user' }]
function readLocal() { try { const value = uni.getStorageSync('yidian-v1'); return value && typeof value === 'object' ? value : {} } catch { return {} } }
const local = readLocal()
const bills = ref(Array.isArray(local.bills) && local.bills.length ? local.bills : initialBills.map(b => ({ ...b })))
const saved = ref(Array.isArray(local.saved) ? local.saved : [])
const contributions = ref(Array.isArray(local.contributions) ? local.contributions : [])
const activePage = ref('discover'), activeCategory = ref('all'), skipped = ref([]), maxAmount = ref(10000), sortOrder = ref('recommended')
const modal = ref(''), toast = ref(''), helpAmount = ref(''), helpError = ref(''), lastContribution = ref(0)
const publishError = ref(''), draftMax = ref(10000), draftSort = ref('recommended')
const publishForm = ref({ title: '', billName: '', amount: '', category: 'daily', story: '', agreed: false })
const publicationCategories = categories.filter(c => c.id !== 'all')
const amountFilters = [{ label: '不限金额', value: 10000 }, { label: '100 元以内', value: 100 }, { label: '200 元以内', value: 200 }, { label: '500 元以内', value: 500 }]
const completed = computed(() => bills.value.filter(b => b.raised >= b.amount).map(b => b.id))
const available = computed(() => eligibleBills(bills.value, activeCategory.value, maxAmount.value, skipped.value, completed.value, sortOrder.value))
const currentBill = computed(() => available.value[0])
const currentPageLabel = computed(() => navigation.find(n => n.id === activePage.value)?.label)
const savedBills = computed(() => bills.value.filter(b => saved.value.includes(b.id)))
const myBills = computed(() => bills.value.filter(b => b.own))
const remaining = computed(() => currentBill.value ? Math.round((currentBill.value.amount - currentBill.value.raised) * 100) / 100 : 0)
const helpPresets = computed(() => [...new Set([10, 30, 50].filter(a => a < remaining.value).concat(remaining.value))])
const totalContributed = computed(() => contributions.value.reduce((sum, c) => sum + c.amount, 0))
const avatarImages = ['/static/images/flower-shop.jpg', '/static/images/kitchen.jpg', '/static/images/study.jpg']
const money = value => Number(value).toFixed(2)
const categoryLabel = id => categories.find(c => c.id === id)?.label || '日常生活'
let toastTimer, leaveTimer
function notify(message) { toast.value = message; clearTimeout(toastTimer); toastTimer = setTimeout(() => { toast.value = '' }, 2600) }
watch([bills, saved, contributions], () => { try { uni.setStorageSync('yidian-v1', { bills: bills.value, saved: saved.value, contributions: contributions.value }) } catch { notify('设备存储空间不足，本次修改暂未保存') } }, { deep: true })
watch(modal, value => { if (value === 'filters') { draftMax.value = maxAmount.value; draftSort.value = sortOrder.value } })
function toggleSave(id) { if (saved.value.includes(id)) { saved.value = saved.value.filter(s => s !== id); notify('已取消收藏') } else { saved.value.push(id); notify('故事已收藏，随时回来看看') } }
const dragX = ref(0), isDragging = ref(false), leaving = ref(false)
let startX = 0, startY = 0, startTime = 0
const cardStyle = computed(() => ({ transform: `translateX(${dragX.value}px) rotate(${dragX.value / 20}deg)`, opacity: leaving.value ? 0 : 1 }))
function eventPoint(event) { return event.touches?.[0] || event.changedTouches?.[0] || event }
function startDrag(event) { if (event.touches?.length > 1) { cancelDrag(); return } if (modal.value || leaving.value || !currentBill.value || (event.type === 'mousedown' && event.button != null && event.button !== 0)) return; const point = eventPoint(event); startX = point.clientX; startY = point.clientY; startTime = Date.now(); isDragging.value = true }
function moveDrag(event) { if (event.touches?.length > 1) { cancelDrag(); return } if (!isDragging.value) return; const point = eventPoint(event); if (Math.abs(point.clientY - startY) > 80 && Math.abs(point.clientX - startX) < 40) { cancelDrag(); return } dragX.value = Math.max(-260, Math.min(260, point.clientX - startX)) }
function endDrag() { if (!isDragging.value) return; isDragging.value = false; const x = dragX.value; dragX.value = 0; if (Math.abs(x) > 85 || (Math.abs(x) > 40 && Date.now() - startTime < 250)) { if (x < 0) skipBill(); else openHelp() } }
function cancelDrag() { isDragging.value = false; dragX.value = 0 }
function skipBill() { if (!currentBill.value || leaving.value) return; const id = currentBill.value.id; leaving.value = true; dragX.value = -280; leaveTimer = setTimeout(() => { skipped.value.push(id); leaving.value = false; dragX.value = 0 }, 220) }
function undoSkip() { if (leaving.value) return; const id = skipped.value.pop(); const bill = bills.value.find(b => b.id === id); if (bill) { activeCategory.value = 'all'; maxAmount.value = 10000; sortOrder.value = 'recommended'; bills.value = [bill, ...bills.value.filter(b => b.id !== id)]; notify('再给这个故事一次相遇') } }
function resetDiscovery() { activeCategory.value = 'all'; skipped.value = []; maxAmount.value = 10000 }
function closeModal() { modal.value = ''; helpError.value = ''; publishError.value = '' }
function openHelp() { if (!currentBill.value || leaving.value) return; helpAmount.value = String(remaining.value); helpError.value = ''; modal.value = 'help' }
function confirmHelp() {
  const amount = Number(helpAmount.value)
  if (!validateHelpAmount(helpAmount.value, remaining.value)) { helpError.value = `请输入 0.01–${money(remaining.value)} 元，最多两位小数`; return }
  const bill = currentBill.value
  if (!bill) return
  contributions.value.unshift({ id: `c-${Date.now()}`, billId: bill.id, name: bill.name, billName: bill.billName, amount, date: new Date().toLocaleString('zh-CN') })
  bill.raised = Math.round((bill.raised + amount) * 100) / 100; bill.people += 1
  lastContribution.value = amount; modal.value = 'success'
}
function applyFilters() { maxAmount.value = draftMax.value; sortOrder.value = draftSort.value; closeModal() }
function showSavedBill(bill) { if (bill.raised >= bill.amount) { notify('这张账单已被温柔接住，去看看别的故事吧'); return } activePage.value = 'discover'; activeCategory.value = 'all'; maxAmount.value = 10000; skipped.value = skipped.value.filter(id => id !== bill.id); bills.value = [bill, ...bills.value.filter(b => b.id !== bill.id)]; sortOrder.value = 'recommended'; modal.value = 'details' }
function openPublish() { publishError.value = ''; modal.value = 'publish' }
function submitPublication() {
  const error = validatePublication(publishForm.value)
  if (error) { publishError.value = error; return }
  const form = publishForm.value
  bills.value.unshift({ ...initialBills[0], id: `own-${Date.now()}`, own: true, name: '一位有心人', age: 25, city: '同一片天空', title: form.title.trim(), billName: form.billName.trim(), story: form.story.trim(), amount: Number(form.amount), raised: 0, people: 0, category: form.category, billType: categoryLabel(form.category), subtitle: '谢谢你愿意停下来，听听我的故事。', tag: '给生活一点希望', date: new Date().toLocaleDateString('zh-CN'), created: Date.now() })
  publishForm.value = { title: '', billName: '', amount: '', category: 'daily', story: '', agreed: false }; closeModal(); activePage.value = 'profile'; notify('演示账单已保存在此设备')
}
onUnmounted(() => { clearTimeout(toastTimer); clearTimeout(leaveTimer) })
</script>

